import { supabase, isSupabaseConfigured } from "@/lib/supabaseClient"

/**
 * Service API untuk tabel public.t_kanban_item (PostgreSQL Supabase)
 * Skema Tabel:
 * - id: bigint generated by default as identity not null (PK)
 * - id_kanban: bigint null
 * - id_karyawan: bigint null
 * - created_at: timestamp with time zone not null default now()
 */
export const kanbanItemApi = {
  /**
   * Mengambil daftar id_karyawan untuk sebuah id_kanban dari public.t_kanban_item
   * @param {number|string} id_kanban
   * @returns {Promise<Array<{id: number, id_kanban: number, id_karyawan: number, created_at: string}>>}
   */
  getItemsByKanbanId: async (id_kanban) => {
    if (!isSupabaseConfigured || !supabase || !id_kanban) return []

    const numericKanbanId = Number(String(id_kanban).replace(/\D/g, "")) || Number(id_kanban)
    if (!numericKanbanId || isNaN(numericKanbanId)) return []

    try {
      const { data, error } = await supabase
        .from("t_kanban_item")
        .select("id, id_kanban, id_karyawan, created_at")
        .eq("id_kanban", numericKanbanId)

      if (error) {
        console.warn("Gagal memuat t_kanban_item:", error.message)
        return []
      }

      return Array.isArray(data) ? data : []
    } catch {
      return []
    }
  },

  /**
   * Mengambil seluruh relasi t_kanban_item
   */
  getAllItems: async () => {
    if (!isSupabaseConfigured || !supabase) return []

    try {
      const { data, error } = await supabase
        .from("t_kanban_item")
        .select("id, id_kanban, id_karyawan, created_at")

      if (error) {
        return []
      }

      return Array.isArray(data) ? data : []
    } catch {
      return []
    }
  },

  /**
   * Menyimpan / sinkronisasi anggota kolaborasi ke public.t_kanban_item
   * Menghapus mapping lama lalu insert baris baru
   * @param {number|string} id_kanban
   * @param {number[]} id_karyawan_list
   */
  syncKanbanItems: async (id_kanban, id_karyawan_list = []) => {
    if (!isSupabaseConfigured || !supabase || !id_kanban) return false

    const numericKanbanId = Number(String(id_kanban).replace(/\D/g, "")) || Number(id_kanban)
    if (!numericKanbanId || isNaN(numericKanbanId)) return false

    try {
      // 1. Hapus entri lama untuk id_kanban ini
      const { error: delError } = await supabase
        .from("t_kanban_item")
        .delete()
        .eq("id_kanban", numericKanbanId)

      if (delError) {
        console.warn("Gagal menghapus entri lama t_kanban_item:", delError.message)
      }

      // 2. Tambahkan entri baru
      if (Array.isArray(id_karyawan_list) && id_karyawan_list.length > 0) {
        const rows = id_karyawan_list
          .map((id_karyawan) => ({
            id_kanban: numericKanbanId,
            id_karyawan: Number(id_karyawan),
          }))
          .filter((row) => !isNaN(row.id_karyawan) && row.id_karyawan > 0)

        if (rows.length > 0) {
          const { error: insError } = await supabase
            .from("t_kanban_item")
            .insert(rows)

          if (insError) {
            console.warn("Gagal menyimpan ke public.t_kanban_item:", insError.message)
            return false
          }
        }
      }

      return true
    } catch (err) {
      console.warn("Exception saat sinkronisasi t_kanban_item:", err)
      return false
    }
  },

  /**
   * Menghapus semua entri t_kanban_item milik id_kanban
   * @param {number|string} id_kanban
   */
  deleteByKanbanId: async (id_kanban) => {
    if (!isSupabaseConfigured || !supabase || !id_kanban) return false

    const numericKanbanId = Number(String(id_kanban).replace(/\D/g, "")) || Number(id_kanban)
    if (!numericKanbanId || isNaN(numericKanbanId)) return false

    try {
      await supabase
        .from("t_kanban_item")
        .delete()
        .eq("id_kanban", numericKanbanId)

      return true
    } catch {
      return false
    }
  },
}
